```kotlin
class LruCache<K, V>(val capacity: Int, private val onEvict: (K, V) -> Unit = { _, _ -> }) {
    init {
        require(capacity >= 1) { "capacity must be >= 1" }
    }

    private val map = LinkedHashMap<K, V>(capacity, 1.0f, true)

    val size: Int get() = map.size

    operator fun get(key: K): V? {
        return map[key]
    }

    operator fun set(key: K, value: V) {
        if (map.containsKey(key)) {
            map[key] = value
        } else {
            map[key] = value
            while (map.size > capacity) {
                val oldestEntry = map.entries.first()
                map.remove(oldestEntry.key)
                onEvict(oldestEntry.key, oldestEntry.value)
            }
        }
    }

    fun remove(key: K): V? {
        return map.remove(key)
    }

    fun keys(): List<K> = map.keys.toList()

    operator fun contains(key: K): Boolean {
        return map.containsKey(key)
    }
}
