            except ValueError:
                raise ValueError(f"Invalid step value '{step_str}'")
            if step <= 0:
                raise ValueError("Step must be positive")
        else:
            base = part

        # Parse the base part (could be *, N, or A-B)
        def _resolve(val_str):
            """Resolve a single value string to an integer."""
            val_str = val_str.strip()
            if name_map and val_str.upper() in name_map:
                return name_map[val_str.upper()]
            try:
                return int(val_str)
            except ValueError:
                raise ValueError(f"Invalid value '{val_str}'")

        if base == '*':
            start = min_val
            end = max_val
        elif '-' in base:
            a_str, b_str = base.split('-', 1)
            a = _resolve(a_str)
            b = _resolve(b_str)
            if a > b:
                raise ValueError(f"Range start {a} greater than end {b}")
            if a < min_val or b > max_val:
                raise ValueError(f"Range {a}-{b} out of bounds [{min_val}, {max_val}]")
            start = a
            end = b
        else:
            val = _resolve(base)
            if val < min_val or val > max_val:
                raise ValueError(f"Value {val} out of range [{min_val}, {max_val}]")
            if has_step:
                # A/S means from A to max
                start = val
                end = max_val
            else:
                start = val
                end = val

        for v in range(start, end + 1, step):
            result.add(v)

    return result


def next_fire(expr: str, after: datetime.datetime) -> datetime.datetime:
    """Find the next fire time for a standard 5-field cron expression."""
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError(f"Expected 5 fields, got {len(fields)}")

    month_names = {
        'JAN': 1, 'FEB': 2, 'MAR': 3, 'APR': 4, 'MAY': 5, 'JUN': 6,
        'JUL': 7, 'AUG': 8, 'SEP': 9, 'OCT': 10, 'NOV': 11, 'DEC': 12
    }
    day_names = {
        'SUN': 0, 'MON': 1, 'TUE': 2, 'WED': 3, 'THU': 4, 'FRI': 5, 'SAT': 6
    }

    try:
        minutes = _parse_field(fields[0], 0, 59)
        hours = _parse_field(fields[1], 0, 23)
        doms = _parse_field(fields[2], 1, 31)
        months = _parse_field(fields[3], 1, 12, month_names)
        dows = _parse_field(fields[4], 0, 7, day_names)
    except ValueError:
        raise

    # Normalize day-of-week: 7 -> 0 (both are Sunday)
    if 7 in dows:
        dows.discard(7)
        dows.add(0)

    # Determine if dom or dow is restricted (not exactly '*')
    dom_restricted = fields[2].strip() != '*'
    dow_restricted = fields[4].strip() != '*'

    def day_matches(day: int, month: int, year: int) -> bool:
        """Check if a given date matches the dom/dow constraints."""
        # Calculate day of week (0=Monday in Python's weekday(), but we need 0=Sunday)
        dt = datetime.date(year, month, day)
        # Python's weekday(): Monday=0 ... Sunday=6
        # Cron: Sunday=0, Monday=1 ... Saturday=6
        cron_dow = (dt.weekday() + 1) % 7

        dom_match = day in doms
        dow_match = cron_dow in dows

        if dom_restricted and dow_restricted:
            # Either matches
            return dom_match or dow_match
        else:
            # Both must match (a * always matches, so the non-restricted one is effectively always True)
            return dom_match and dow_match

    # Start from the next minute after `after`
    current = after.replace(second=0, microsecond=0) + datetime.timedelta(minutes=1)

    limit = after + datetime.timedelta(days=365 * 5)

    while current < limit:
        if current.month not in months:
            # Jump to the first day of the next month
            if current.month == 12:
                current = current.replace(year=current.year + 1, month=1, day=1, hour=0, minute=0)
            else:
                current = current.replace(month=current.month + 1, day=1, hour=0, minute=0)
            continue

        if not day_matches(current.day, current.month, current.year):
            # Jump to the next day
            current = (current + datetime.timedelta(days=1)).replace(hour=0, minute=0)
            continue

        if current.hour not in hours:
            # Jump to the next hour
            current = (current + datetime.timedelta(hours=1)).replace(minute=0)
            continue

        if current.minute not in minutes:
            # Jump to the next minute
            current = current + datetime.timedelta(minutes=1)
            continue

        # All fields match
        return current

    raise ValueError("No matching time found within 5 years")
```

The key insight for `unflatten`: segments are dict keys by default; a segment becomes a list index **only when the parent node is already a list** (i.e., some earlier sibling segment forced it to be a list). This naturally handles nested dicts with numeric-looking keys (`a.b` stays a dict) and avoids the false-positive conversion of `{"a": {"0": 1}}`.

```python
def flatten(obj, sep=".") -> dict:
    if not isinstance(obj, dict):
        raise TypeError("Top-level object must be a dict")

    result = {}

    def _validate_key(key):
        if not isinstance(key, str):
            raise ValueError(f"Key must be a string: {key!r}")
        if sep in key:
            raise ValueError(f"Key contains separator: {key!r}")

    def _flatten_value(value, full_key, result):
        """Recursively flatten `value` under path prefix `full_key`."""
        if isinstance(value, dict):
            if len(value) == 0:
                result[full_key] = {}
            else:
                for k, v in value.items():
                    _validate_key(k)
                    child_key = f"{full_key}{sep}{k}"
                    _flatten_value(v, child_key, result)
        elif isinstance(value, list):
            if len(value) == 0:
                result[full_key] = []
            else:
                for i, item in enumerate(value):
                    child_key = f"{full_key}{sep}{i}"
                    _flatten_value(item, child_key, result)
        else:
            result[full_key] = value

    for key, value in obj.items():
        _validate_key(key)
        _flatten_value(value, key, result)

    return result


def unflatten(flat: dict, sep=".") -> dict:
    if not isinstance(flat, dict):
        raise TypeError("Input must be a dict")

    def _is_valid_index(s):
        """Non-negative integer without leading zeros (e.g. '0', '12')."""
        if not isinstance(s, str) or len(s) == 0:
            return False
        if not s.isdigit():
            return False
        if len(s) > 1 and s[0] == "0":
            return False
        return True

    root = {}

    for key in flat.keys():
        parts = key.split(sep)
        node = root
        for i, part in enumerate(parts[:-1]):
            if isinstance(node, list):
                # Parent is a list -> segment must be a valid index.
                if not _is_valid_index(part):
                    raise ValueError(f"Invalid list index: {part!r}")
                idx = int(part)
                while len(node) <= idx:
                    node.append({})
                node = node[idx]
            else:
                # Parent is a dict -> segment is a dict key.
                if part not in node:
                    node[part] = {}
                node = node[part]

        last = parts[-1]
        if isinstance(node, list):
            if not _is_valid_index(last):
                raise ValueError(f"Invalid list index: {last!r}")
            idx = int(last)
            while len(node) <= idx:
                node.append(None)
            if node[idx] is not None:
                raise ValueError(f"Conflict at index {idx}")
            node[idx] = flat[key]
        else:
            # Dict container. If the key already exists as a non-container, conflict.
            if last in node and isinstance(node[last], (dict, list)):
                raise ValueError(f"Conflict: {last!r} is already a container")
            if last in node and not isinstance(node[last], (dict, list)):
                # Existing leaf value -> conflict with new assignment unless identical? Spec says conflict.
                raise ValueError(f"Conflict: {last!r} is already set")
            node[last] = flat[key]

    return root
