def unflatten(flat: dict, sep=".") -> dict:
    if not isinstance(flat, dict):
        raise TypeError("Input must be a dict")

    def _is_valid_index(s):
        if not isinstance(s, str) or len(s) == 0:
            return False
        if not s.isdigit():
            return False
        if len(s) > 1 and s[0] == "0":
            return False
        return True

    # Validate all keys first
    for key in flat.keys():
        if not isinstance(key, str):
            raise ValueError(f"Key must be a string: {key!r}")
        parts = key.split(sep)
        for p in parts:
            if p == "":
                raise ValueError(f"Empty segment in key: {key!r}")

    root = {}
    list_filled = {}  # id(list) -> set of filled indices

    for key in flat.keys():
        parts = key.split(sep)
        node = root
        for i, part in enumerate(parts[:-1]):
            if isinstance(node, list):
                if not _is_valid_index(part):
                    raise ValueError(f"Invalid list index: {part!r}")
                idx = int(part)
                while len(node) <= idx:
                    node.append({})
                if id(node) not in list_filled:
                    list_filled[id(node)] = set()
                list_filled[id(node)].add(idx)
                node = node[idx]
            elif isinstance(node, dict):
                if part not in node:
                    node[part] = {}
                node = node[part]
                # After descending, check that node is a container (dict or list)
                # If it's a leaf value, we have a conflict
                if not isinstance(node, (dict, list)):
                    raise ValueError(f"Conflict: cannot descend into leaf value at {part!r}")
            else:
                # node is a leaf value (int, str, None, etc.)
                raise ValueError(f"Conflict: cannot descend into leaf value at {part!r}")

        last = parts[-1]
        if isinstance(node, list):
            if not _is_valid_index(last):
                raise ValueError(f"Invalid list index: {last!r}")
            idx = int(last)
            while len(node) <= idx:
                node.append(None)
            if id(node) not in list_filled:
                list_filled[id(node)] = set()
            if idx in list_filled[id(node)]:
                raise ValueError(f"Conflict at index {idx}")
            list_filled[id(node)].add(idx)
            node[idx] = flat[key]
        elif isinstance(node, dict):
            if last in node:
                existing = node[last]
                if isinstance(existing, (dict, list)):
                    # This is a conflict: the key was set as a leaf container value
                    raise ValueError(f"Conflict: {last!r} is already a container leaf")
                else:
                    raise ValueError(f"Conflict: {last!r} is already set")
            node[last] = flat[key]
        else:
            raise ValueError(f"Conflict: cannot assign to non-container")

    # Validate density of all lists
    def _validate_lists(obj):
        if isinstance(obj, dict):
            for v in obj.values():
                _validate_lists(v)
        elif isinstance(obj, list):
            filled = list_filled.get(id(obj), set())
            if len(filled) != len(obj):
                raise ValueError(
                    f"List is not dense: expected indices 0..{len(obj)-1}, got {sorted(filled)}"
                )
            for i in range(len(obj)):
                if i not in filled:
                    raise ValueError(f"List has gap at index {i}")
                _validate_lists(obj[i])

    _validate_lists(root)

    return root
