```python
"""A small expression language interpreter.

Grammar (lowest to highest precedence):
1. `a ? b : c` conditional, right-associative; `a` is true when non-zero. Only the chosen branch is evaluated.
2. `||` then `&&` (short-circuit; result is 1 or 0).
3. comparisons `== != < <= > >=`, non-associative: `1 < 2 < 3` is an error. Result 1 or 0.
4. `+ -` left-associative.
5. `* / %` left-associative. `/` on two ints gives an int when it divides exactly, else a float. `%` follows Python semantics.
6. unary `-`, `+`, `!` (`!x` is 1 if x == 0 else 0).
7. `^` power, right-associative, binds tighter than unary minus on its left: `-2^2` is -4, `2^-1` is 0.5, `2^3^2` is 512.
8. atoms: integer literals (`42`), decimal literals (`1.5`, `.5`, `2.`), identifiers `[A-Za-z_][A-Za-z0-9_]*` looked up in `env`, function calls `min(...)`, `max(...)` (1 or more args), `abs(x)`, and parentheses.

Whitespace is ignored between tokens. Errors: raise `ZeroDivisionError` for division or modulo by zero,
`NameError` for unknown variables or functions, and `SyntaxError` for anything malformed (including wrong
argument counts for `abs`, empty input, trailing tokens, a lone `=`, `&`, `|`).
"""

from __future__ import annotations


# Token types
TOK_INT = "INT"
TOK_FLOAT = "FLOAT"
TOK_IDENT = "IDENT"
TOK_OP = "OP"
TOK_LPAREN = "LPAREN"
TOK_RPAREN = "RPAREN"
TOK_COMMA = "COMMA"
TOK_EOF = "EOF"


class _Token:
    __slots__ = ("kind", "value")

    def __init__(self, kind: str, value):
        self.kind = kind
        self.value = value

    def __repr__(self) -> str:
        return f"Token({self.kind!r}, {self.value!r})"


# Two-character operators (checked before one-char)
_TWO_CHAR_OPS = ("==", "!=", "<=", ">=", "||", "&&")
_ONE_CHAR_CHARS = "+-*/%^<>=!&|?:"


def _tokenize(expr: str) -> list[_Token]:
    tokens: list[_Token] = []
    i = 0
    n = len(expr)

    while i < n:
        ch = expr[i]

        # Skip whitespace
        if ch.isspace():
            i += 1
            continue

        # Two-character operators
        if i + 1 < n and expr[i : i + 2] in _TWO_CHAR_OPS:
            tokens.append(_Token(TOK_OP, expr[i : i + 2]))
            i += 2
            continue

        # One-character operators / punctuation
        if ch in _ONE_CHAR_CHARS:
            tokens.append(_Token(TOK_OP, ch))
            i += 1
            continue

        if ch == "(":
            tokens.append(_Token(TOK_LPAREN, "("))
            i += 1
            continue

        if ch == ")":
            tokens.append(_Token(TOK_RPAREN, ")"))
            i += 1
            continue

        if ch == ",":
            tokens.append(_Token(TOK_COMMA, ","))
            i += 1
            continue

        # Numbers: integer or decimal literals
        if ch.isdigit() or (ch == "." and i + 1 < n and expr[i + 1].isdigit()):
            start = i
            has_dot = False
            # Integer part
            while i < n and expr[i].isdigit():
                i += 1
            # Decimal part
            if i < n and expr[i] == ".":
                has_dot = True
                i += 1
                while i < n and expr[i].isdigit():
                    i += 1
            text = expr[start:i]

            # Validate: reject malformed numbers
            if has_dot:
                dot_count = text.count(".")
                if dot_count != 1:
                    raise SyntaxError(f"Malformed number literal {text!r}")
                int_part, frac_part = text.split(".")
                if not int_part and not frac_part:
                    raise SyntaxError(f"Malformed number literal {text!r}")

            if has_dot:
                tokens.append(_Token(TOK_FLOAT, float(text)))
            else:
                tokens.append(_Token(TOK_INT, int(text)))
            continue

        # Identifiers / function names
        if ch.isalpha() or ch == "_":
            start = i
            while i < n and (expr[i].isalnum() or expr[i] == "_"):
                i += 1
            tokens.append(_Token(TOK_IDENT, expr[start:i]))
            continue

        raise SyntaxError(f"Unexpected character {ch!r} at position {i}")

    tokens.append(_Token(TOK_EOF, None))
    return tokens


class _Parser:
    def __init__(self, tokens: list[_Token], env: dict[str, float] | None):
        self.tokens = tokens
        self.pos = 0
        self.env = env if env is not None else {}

    def peek(self) -> _Token:
        return self.tokens[self.pos]

    def advance(self) -> _Token:
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def expect(self, kind: str, value=None) -> _Token:
        tok = self.peek()
        if tok.kind != kind or (value is not None and tok.value != value):
            raise SyntaxError(f"Expected {kind} {value!r} but got {tok!r}")
        return self.advance()

    def parse(self) -> int | float:
        result = self.parse_conditional(evaluate=True)
        if self.peek().kind != TOK_EOF:
            raise SyntaxError(f"Unexpected token {self.peek()!r} after expression")
        return result

    # 1. Conditional: a ? b : c (right-associative, lazy evaluation)
    def parse_conditional(self, evaluate: bool = True) -> int | float:
        cond = self.parse_or(evaluate=evaluate)
        if self.peek().kind == TOK_OP and self.peek().value == "?":
            self.advance()  # consume '?'
            if evaluate:
                if cond != 0:
                    # Evaluate true branch, skip false branch
                    result = self.parse_or(evaluate=True)
                    self._expect_colon()
                    # Parse (but don't evaluate) false branch
                    self.parse_conditional(evaluate=False)
                    return result
                else:
                    # Skip true branch, evaluate false branch
                    self.parse_or(evaluate=False)
                    self._expect_colon()
                    result = self.parse_conditional(evaluate=True)
                    return result
            else:
                # Not evaluating: skip both branches
                self.parse_or(evaluate=False)
                self._expect_colon()
                self.parse_conditional(evaluate=False)
                return 0
        return cond

    def _expect_colon(self):
        tok = self.peek()
        if tok.kind == TOK_OP and tok.value == ":":
            self.advance()
        else:
            raise SyntaxError(f"Expected ':' but got {tok!r}")

    # 2. || (lowest of logical, short-circuit)
    def parse_or(self, evaluate: bool = True) -> int | float:
        left = self.parse_and(evaluate=evaluate)
        while self.peek().kind == TOK_OP and self.peek().value == "||":
            self.advance()
            if evaluate and left != 0:
                # Short-circuit: skip right side
                self.parse_and(evaluate=False)
                left = 1
            else:
                right = self.parse_and(evaluate=evaluate)
                if evaluate:
                    left = 1 if (left != 0 or right != 0) else 0
        return left

    # 2. && (higher than ||, short-circuit)
    def parse_and(self, evaluate: bool = True) -> int | float:
        left = self.parse_comparison(evaluate=evaluate)
        while self.peek().kind == TOK_OP and self.peek().value == "&&":
            self.advance()
            if evaluate and left == 0:
                # Short-circuit: skip right side
                self.parse_comparison(evaluate=False)
                left = 0
            else:
                right = self.parse_comparison(evaluate=evaluate)
                if evaluate:
                    left = 1 if (left != 0 and right != 0) else 0
        return left

    # 3. Comparisons (non-associative)
    def parse_comparison(self, evaluate: bool = True) -> int | float:
        left = self.parse_additive(evaluate=evaluate)
        tok = self.peek()
        if tok.kind == TOK_OP and tok.value in ("==", "!=", "<", "<=", ">", ">="):
            self.advance()
            right = self.parse_additive(evaluate=evaluate)
            # Check for non-associativity: another comparison op following
            next_tok = self.peek()
            if next_tok.kind == TOK_OP and next_tok.value in ("==", "!=", "<", "<=", ">", ">="):
                raise SyntaxError(
                    f"Non-associative comparison: {left!r} {tok.value} {right!r} followed by {next_tok.value!r}"
                )
            if evaluate:
                op = tok.value
                if op == "==":
                    return 1 if left == right else 0
                elif op == "!=":
                    return 1 if left != right else 0
                elif op == "<":
                    return 1 if left < right else 0
                elif op == "<=":
                    return 1 if left <= right else 0
                elif op == ">":
                    return 1 if left > right else 0
                elif op == ">=":
                    return 1 if left >= right else 0
            return 0
        return left

    # 4. Additive: + - (left-associative)
    def parse_additive(self, evaluate: bool = True) -> int | float:
        left = self.parse_multiplicative(evaluate=evaluate)
        while True:
            tok = self.peek()
            if tok.kind == TOK_OP and tok.value in ("+", "-"):
                self.advance()
                right = self.parse_multiplicative(evaluate=evaluate)
                if evaluate:
                    if tok.value == "+":
                        left = left + right
                    else:
                        left = left - right
            else:
                break
        return left

    # 5. Multiplicative: * / % (left-associative)
    def parse_multiplicative(self, evaluate: bool = True) -> int | float:
        left = self.parse_unary(evaluate=evaluate)
        while True:
            tok = self.peek()
            if tok.kind == TOK_OP and tok.value in ("*", "/", "%"):
                self.advance()
                right = self.parse_unary(evaluate=evaluate)
                if evaluate:
                    if tok.value == "*":
                        left = left * right
                    elif tok.value == "/":
                        if right == 0:
                            raise ZeroDivisionError("division by zero")
                        if (
                            isinstance(left, int)
                            and not isinstance(left, bool)
                            and isinstance(right, int)
                            and not isinstance(right, bool)
                        ):
                            if left % right == 0:
                                left = left // right
                            else:
                                left = left / right
                        else:
                            left = left / right
                    elif tok.value == "%":
                        if right == 0:
                            raise ZeroDivisionError("modulo by zero")
                        left = left % right
            else:
                break
        return left

    # 6. Unary: - + ! (prefix)
    def parse_unary(self, evaluate: bool = True) -> int | float:
        tok = self.peek()
        if tok.kind == TOK_OP and tok.value in ("-", "+", "!"):
            self.advance()
            operand = self.parse_unary(evaluate=evaluate)
            if evaluate:
                if tok.value == "-":
                    return -operand
                elif tok.value == "+":
                    return +operand
                elif tok.value == "!":
                    return 1 if operand == 0 else 0
            return 0
        return self.parse_power(evaluate=evaluate)

    # 7. Power: ^ (right-associative)
    def parse_power(self, evaluate: bool = True) -> int | float:
        base = self.parse_atom(evaluate=evaluate)
        if self.peek().kind == TOK_OP and self.peek().value == "^":
            self.advance()
            # Exponent can have unary operators (e.g., 2^-1)
            exponent = self.parse_unary(evaluate=evaluate)
            if evaluate:
                return base ** exponent
            return 0
        return base

    # 8. Atoms: literals, identifiers, function calls, parentheses
    def parse_atom(self, evaluate: bool = True) -> int | float:
        tok = self.peek()

        if tok.kind == TOK_INT:
            self.advance()
            return tok.value

        if tok.kind == TOK_FLOAT:
            self.advance()
            return tok.value

        if tok.kind == TOK_IDENT:
            name = tok.value
            self.advance()
            # Check for function call
            if self.peek().kind == TOK_LPAREN:
                self.advance()  # consume '('
                args = self._parse_arg_list(evaluate=evaluate)
                self.expect(TOK_RPAREN)  # expect ')'
                if evaluate:
                    return self._call_function(name, args)
                return 0
            else:
                # Variable lookup
                if evaluate:
                    if name in self.env:
                        return self.env[name]
                    raise NameError(f"Name {name!r} is not defined")
                return 0

        if tok.kind == TOK_LPAREN:
            self.advance()  # consume '('
            expr = self.parse_conditional(evaluate=evaluate)
            self.expect(TOK_RPAREN)  # expect ')'
            return expr

        raise SyntaxError(f"Unexpected token {tok!r}")

    def _parse_arg_list(self, evaluate: bool = True) -> list[int | float]:
        args: list[int | float] = []
        if self.peek().kind == TOK_RPAREN:
            return args  # empty argument list (validated later)
        args.append(self.parse_conditional(evaluate=evaluate))
        while self.peek().kind == TOK_COMMA:
            self.advance()  # consume ','
            args.append(self.parse_conditional(evaluate=evaluate))
        return args

    def _call_function(self, name: str, args: list[int | float]) -> int | float:
        if name == "min":
            if len(args) < 1:
                raise SyntaxError("min() requires at least 1 argument")
            result = args[0]
            for a in args[1:]:
                if a < result:
                    result = a
            return result
        elif name == "max":
            if len(args) < 1:
                raise SyntaxError("max() requires at least 1 argument")
            result = args[0]
            for a in args[1:]:
                if a > result:
                    result = a
            return result
        elif name == "abs":
            if len(args) != 1:
                raise SyntaxError("abs() requires exactly 1 argument")
            return abs(args[0])
        else:
            raise NameError(f"Function {name!r} is not defined")


def evaluate(expr: str, env: dict[str, float] | None = None) -> int | float:
    """Evaluate an expression in the small expression language.

    Args:
        expr: The expression string to evaluate.
        env: Optional dictionary of variable names to float values.

    Returns:
        The result as an int or float.

    Raises:
        ZeroDivisionError: For division or modulo by zero.
        NameError: For unknown variables or functions.
        SyntaxError: For malformed expressions.
    """
    if not expr.strip():
        raise SyntaxError("Empty expression")

    tokens = _tokenize(expr)
    parser = _Parser(tokens, env)
    return parser.parse()
