import heapq


def route(grid: list[str]) -> tuple[int, str] | None:
    if not grid:
        raise ValueError("Empty grid")

    R = len(grid)
    C = len(grid[0])

    # Validate grid
    s_count = 0
    e_count = 0
    start = None
    end = None
    pads = {}

    for r in range(R):
        row = grid[r]
        if len(row) != C:
            raise ValueError("Ragged rows")
        for c in range(C):
            ch = row[c]
            if ch == 'S':
                s_count += 1
                start = (r, c)
            elif ch == 'E':
                e_count += 1
                end = (r, c)
            elif ch == '#' or ch == '.':
                pass
            elif '1' <= ch <= '9':
                pass
            elif 'a' <= ch <= 'z':
                if ch not in pads:
                    pads[ch] = []
                pads[ch].append((r, c))
            else:
                raise ValueError(f"Unknown character: {ch}")

    if s_count != 1:
        raise ValueError("Not exactly one S")
    if e_count != 1:
        raise ValueError("Not exactly one E")

    for ch, positions in pads.items():
        if len(positions) == 1 or len(positions) > 2:
            raise ValueError(f"Letter {ch} appears {len(positions)} times, must be 0 or 2")

    pad_map = {}
    for ch, positions in pads.items():
        if len(positions) == 2:
            pad_map[positions[0]] = positions[1]
            pad_map[positions[1]] = positions[0]

    def get_cost(r, c):
        ch = grid[r][c]
        if ch in ('S', 'E', '.'):
            return 1
        elif '1' <= ch <= '9':
            return int(ch)
        elif 'a' <= ch <= 'z':
            return 1
        else:
            return 0

    # Dijkstra with lexicographic tie-breaking.
    # We run full Dijkstra, tracking for each node the best (cost, moves) pair.
    # The heap contains (cost, moves, r, c). Python compares tuples element-wise.
    # When we pop a state, if it's worse than what we already have for that node, skip.
    # We only finalize a node when we pop its best entry.

    INF = float('inf')
    dist = [[INF] * C for _ in range(R)]
    best_moves = [[""] * C for _ in range(R)]
    finalized = [[False] * C for _ in range(R)]

    sr, sc = start
    er, ec = end

    dist[sr][sc] = 0
    best_moves[sr][sc] = ""

    heap = [(0, "", sr, sc)]

    while heap:
        cost, moves, r, c = heapq.heappop(heap)

        # Skip if this entry is worse than what we've recorded
        if cost > dist[r][c]:
            continue
        if cost == dist[r][c] and moves >= best_moves[r][c]:
            continue

        # If already finalized with a better or equal state, skip
        if finalized[r][c]:
            continue

        # This is the best known state for (r, c); finalize it.
        finalized[r][c] = True

        if (r, c) == (er, ec):
            return (cost, moves)

        # Generate neighbors in order of move alphabet: D < L < R < T < U
        # Moves: D=(1,0), L=(0,-1), R=(0,1), U=(-1,0), T=teleport
        for dr, dc, move in [(1, 0, 'D'), (0, -1, 'L'), (0, 1, 'R'), (-1, 0, 'U')]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < R and 0 <= nc < C:
                if grid[nr][nc] == '#':
                    continue
                ncost = cost + get_cost(nr, nc)
                nmoves = moves + move
                if ncost < dist[nr][nc]:
                    dist[nr][nc] = ncost
                    best_moves[nr][nc] = nmoves
                    heapq.heappush(heap, (ncost, nmoves, nr, nc))
                elif ncost == dist[nr][nc] and nmoves < best_moves[nr][nc]:
                    best_moves[nr][nc] = nmoves
                    heapq.heappush(heap, (ncost, nmoves, nr, nc))

        # Teleport move T
        if (r, c) in pad_map:
            tr, tc = pad_map[(r, c)]
            ncost = cost + 2
            nmoves = moves + 'T'
            if ncost < dist[tr][tc]:
                dist[tr][tc] = ncost
                best_moves[tr][tc] = nmoves
                heapq.heappush(heap, (ncost, nmoves, tr, tc))
            elif ncost == dist[tr][tc] and nmoves < best_moves[tr][tc]:
                best_moves[tr][tc] = nmoves
                heapq.heappush(heap, (ncost, nmoves, tr, tc))

    # If we never reached E
    if dist[er][ec] == INF:
        return None
    return (dist[er][ec], best_moves[er][ec])
