import re
from dataclasses import dataclass, field
from functools import total_ordering
from typing import List, Optional, Tuple


@total_ordering
@dataclass
class Version:
    major: int
    minor: int
    patch: int
    prerelease: Optional[str] = None
    build: Optional[str] = None

    def __post_init__(self):
        if self.prerelease is not None and self.prerelease == "":
            raise ValueError("Empty prerelease")
        if self.build is not None and self.build == "":
            raise ValueError("Empty build")

    @property
    def key(self) -> tuple:
        """Return a sort key for SemVer precedence comparison."""
        pre = self.prerelease
        if pre is None:
            return (self.major, self.minor, self.patch, 1, ())
        else:
            ids = pre.split(".")
            key_parts = []
            for ident in ids:
                if ident.isdigit():
                    key_parts.append((0, int(ident), ""))
                else:
                    key_parts.append((1, 0, ident))
            return (self.major, self.minor, self.patch, 0, tuple(key_parts))

    def __eq__(self, other) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self.key == other.key

    def __lt__(self, other) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self.key < other.key

    def __le__(self, other) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self.key <= other.key

    def __gt__(self, other) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self.key > other.key

    def __ge__(self, other) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self.key >= other.key


