    """Parse a numeric identifier with no leading zeros."""
    if s == "":
        raise ValueError("Empty identifier")
    if len(s) > 1 and s[0] == "0":
        raise ValueError(f"Leading zero in numeric identifier: {s}")
    return int(s)


def _parse_prerelease(s: str) -> Optional[str]:
    """Validate prerelease string."""
    if s is None or s == "":
        return None
    ids = s.split(".")
    for ident in ids:
        if not re.match(r'^[0-9A-Za-z-]+$', ident):
            raise ValueError(f"Invalid prerelease identifier: {ident}")
        if ident.isdigit():
            if len(ident) > 1 and ident[0] == "0":
                raise ValueError(f"Leading zero in numeric prerelease identifier: {ident}")
