    prerelease = None
    dash_idx = s.find("-")
    if dash_idx != -1:
        s_core = s[:dash_idx]
        pre_str = s[dash_idx + 1:]
        prerelease = _parse_prerelease(pre_str)
        if prerelease is None:
            raise ValueError("Empty prerelease")
    else:
        s_core = s

    # Parse MAJOR.MINOR.PATCH
    parts = s_core.split(".")
    if len(parts) < 1 or len(parts) > 3:
        raise ValueError(f"Invalid version format: {s_core}")

    try:
