"""npm-style semantic version ranges."""

import re
from dataclasses import dataclass, field
from functools import total_ordering
from typing import List, Optional, Tuple


@total_ordering
@dataclass
class Version:
    major: int
    minor: int
    patch: int
    prerelease: Optional[str] = None
    build: Optional[str] = None

    def __post_init__(self):
        if self.prerelease is not None and self.prerelease == "":
            raise ValueError("Empty prerelease")
        if self.build is not None and self.build == "":
            raise ValueError("Empty build")

    @property
    def key(self) -> tuple:
        """Return a sort key for SemVer precedence comparison."""
        pre = self.prerelease
        if pre is None:
            return (self.major, self.minor, self.patch, 1, ())
        else:
            ids = pre.split(".")
            key_parts = []
            for ident in ids:
                if re.match(r'^[0-9]+$', ident):
                    key_parts.append((0, int(ident), ""))
                else:
                    key_parts.append((1, 0, ident))
            return (self.major, self.minor, self.patch, 0, tuple(key_parts))

    def __eq__(self, other) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self.key == other.key

    def __lt__(self, other) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self.key < other.key

    def __le__(self, other) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self.key <= other.key

    def __gt__(self, other) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self.key > other.key

    def __ge__(self, other) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self.key >= other.key


def _parse_identifier(s: str) -> int:
    """Parse a numeric identifier with no leading zeros."""
    if s == "":
        raise ValueError("Empty identifier")
    if len(s) > 1 and s[0] == "0":
        raise ValueError(f"Leading zero in numeric identifier: {s}")
    return int(s)


def _parse_prerelease(s: str) -> Optional[str]:
    """Validate prerelease string."""
    if s is None or s == "":
        return None
    ids = s.split(".")
    for ident in ids:
        if not re.match(r'^[0-9A-Za-z-]+$', ident):
            raise ValueError(f"Invalid prerelease identifier: {ident}")
        if re.match(r'^[0-9]+$', ident):
            if len(ident) > 1 and ident[0] == "0":
                raise ValueError(f"Leading zero in numeric prerelease identifier: {ident}")
    return s


def _parse_build(s: str) -> Optional[str]:
    """Validate build metadata string."""
    if s is None or s == "":
        return None
    ids = s.split(".")
    for ident in ids:
        if not re.match(r'^[0-9A-Za-z-]+$', ident):
            raise ValueError(f"Invalid build identifier: {ident}")
    return s


def parse(v: str) -> Version:
    """Parse a SemVer 2.0.0 version string."""
    if not isinstance(v, str):
        raise ValueError("Input must be a string")

    s = v.strip()
    if s == "":
        raise ValueError("Empty version string")

    # Strip leading 'v' or '='
    if s[0] in ('v', '='):
        s = s[1:]

    if s == "":
        raise ValueError("Empty version after prefix")

    # Split off build metadata
    build = None
    if "+" in s:
        parts = s.split("+", 1)
        s = parts[0]
        build_str = parts[1]
        build = _parse_build(build_str)
        if build is None:
            raise ValueError("Empty build metadata")

    # Split off prerelease: find the first '-' in the remaining string
    prerelease = None
    dash_idx = s.find("-")
    if dash_idx != -1:
        s_core = s[:dash_idx]
        pre_str = s[dash_idx + 1:]
        prerelease = _parse_prerelease(pre_str)
        if prerelease is None:
            raise ValueError("Empty prerelease")
    else:
        s_core = s

    # Parse MAJOR.MINOR.PATCH - must be exactly 3 parts
    parts = s_core.split(".")
    if len(parts) != 3:
        raise ValueError(f"Invalid version format, expected MAJOR.MINOR.PATCH: {s_core}")

    try:
        major = _parse_identifier(parts[0])
        minor = _parse_identifier(parts[1])
        patch = _parse_identifier(parts[2])
    except ValueError as e:
        raise ValueError(f"Invalid version: {v}") from e

    return Version(major, minor, patch, prerelease, build)


@dataclass
class Comparator:
    op: str
    version: Version

    def matches(self, v: Version) -> bool:
        if self.op == "<":
            return v < self.version
        elif self.op == "<=":
            return v <= self.version
        elif self.op == ">":
            return v > self.version
        elif self.op == ">=":
            return v >= self.version
        elif self.op == "=":
            return v == self.version
        return False


def _parse_version_parts(s: str) -> Tuple[Optional[int], Optional[int], Optional[int], Optional[str]]:
    """Parse version parts, allowing X-ranges. Returns (major, minor, patch, prerelease)."""
    s = s.strip()
    if s == "":
        raise ValueError("Empty version")

    # Strip leading v or =
    if s[0] in ('v', '='):
        s = s[1:]

    if s == "":
        raise ValueError("Empty version after prefix")

    # Split off build metadata (ignored for range matching but must be valid)
    if "+" in s:
        parts = s.split("+", 1)
        s = parts[0]
        _parse_build(parts[1])  # validate but discard

    # Split off prerelease using first '-'
    prerelease = None
    dash_idx = s.find("-")
    if dash_idx != -1:
        s_core = s[:dash_idx]
        pre_str = s[dash_idx + 1:]
        prerelease = _parse_prerelease(pre_str)
        if prerelease is None:
            raise ValueError("Empty prerelease in range comparator")
    else:
        s_core = s

    # Parse M.m.p with X support
    core_parts = s_core.split(".")
    if len(core_parts) > 3:
        raise ValueError(f"Too many version parts: {s_core}")

    major = None
    minor = None
    patch = None

    if len(core_parts) >= 1:
        p = core_parts[0]
        if p in ("x", "X", "*"):
            major = None
        elif p == "":
            raise ValueError(f"Empty version part: {s_core}")
        else:
            major = _parse_identifier(p)

    if len(core_parts) >= 2:
        p = core_parts[1]
        if p in ("x", "X", "*"):
            minor = None
        elif p == "":
            raise ValueError(f"Empty version part: {s_core}")
        else:
            minor = _parse_identifier(p)

    if len(core_parts) >= 3:
        p = core_parts[2]
        if p in ("x", "X", "*"):
            patch = None
        elif p == "":
            raise ValueError(f"Empty version part: {s_core}")
        else:
            patch = _parse_identifier(p)

    return major, minor, patch, prerelease


def _expand_partial_version(s: str, op: str) -> List[Comparator]:
    """Expand a possibly partial version with an operator into comparators."""
    major, minor, patch, prerelease = _parse_version_parts(s)

    # If major is None, it's like * or x - matches everything
    if major is None:
        return []

    # Major is specified, minor is None (e.g., "1" or "1.x")
    if minor is None:
        if op == ">":
            return [Comparator(">=", Version(major + 1, 0, 0))]
        elif op == "<":
            return [Comparator("<", Version(major, 0, 0))]
        elif op == ">=":
            return [Comparator(">=", Version(major, 0, 0))]
        elif op == "<=":
            return [Comparator("<", Version(major + 1, 0, 0))]
        else:  # '=' or none
            return [Comparator(">=", Version(major, 0, 0)), Comparator("<", Version(major + 1, 0, 0))]

    # Major and minor specified, patch is None (e.g., "1.2" or "1.2.x")
    if patch is None:
        if op == ">":
            return [Comparator(">=", Version(major, minor + 1, 0))]
        elif op == "<":
            return [Comparator("<", Version(major, minor, 0))]
        elif op == ">=":
            return [Comparator(">=", Version(major, minor, 0))]
        elif op == "<=":
            return [Comparator("<", Version(major, minor + 1, 0))]
        else:  # '=' or none
            return [Comparator(">=", Version(major, minor, 0)), Comparator("<", Version(major, minor + 1, 0))]

    # Full version specified
    v = Version(major, minor, patch, prerelease)
    return [Comparator(op, v)]


def _parse_tilde(s: str) -> List[Comparator]:
    """Parse tilde range."""
    s = s.strip()
    major, minor, patch, prerelease = _parse_version_parts(s)

    if major is None:
        raise ValueError(f"Invalid tilde range: {s}")

    if minor is None:
        return [Comparator(">=", Version(major, 0, 0)), Comparator("<", Version(major + 1, 0, 0))]

    if patch is None:
        return [Comparator(">=", Version(major, minor, 0)), Comparator("<", Version(major, minor + 1, 0))]

    return [Comparator(">=", Version(major, minor, patch, prerelease)), Comparator("<", Version(major, minor + 1, 0))]


def _parse_caret(s: str) -> List[Comparator]:
    """Parse caret range."""
    s = s.strip()
    major, minor, patch, prerelease = _parse_version_parts(s)

    if major is None:
        raise ValueError(f"Invalid caret range: {s}")

    if minor is None:
        return [Comparator(">=", Version(major, 0, 0)), Comparator("<", Version(major + 1, 0, 0))]

    if patch is None:
        if major == 0 and minor == 0:
            return [Comparator(">=", Version(0, 0, 0)), Comparator("<", Version(0, 1, 0))]
        elif major == 0:
            return [Comparator(">=", Version(0, 0, 0)), Comparator("<", Version(1, 0, 0))]
        else:
            return [Comparator(">=", Version(major, minor, 0)), Comparator("<", Version(major + 1, 0, 0))]

    # Full version specified
    if major == 0:
        if minor == 0:
            return [Comparator(">=", Version(0, 0, patch, prerelease)), Comparator("<", Version(0, 0, patch + 1))]
        else:
            return [Comparator(">=", Version(0, minor, patch, prerelease)), Comparator("<", Version(0, minor + 1, 0))]
    else:
        return [Comparator(">=", Version(major, minor, patch, prerelease)), Comparator("<", Version(major + 1, 0, 0))]


def _parse_hyphen(s: str) -> List[Comparator]:
    """Parse hyphen range like '1.2.3 - 2.3.4'."""
    # Use regex to find the hyphen separator with optional surrounding spaces
    m = re.match(r'^(\S+)\s*-\s*(\S+)$', s)
    if not m:
        raise ValueError(f"Invalid hyphen range: {s}")

    lower_str = m.group(1).strip()
    upper_str = m.group(2).strip()

    # Parse lower bound (fill zeros for partial)
    major, minor, patch, prerelease = _parse_version_parts(lower_str)
    if major is None:
        major = 0
    if minor is None:
        minor = 0
    if patch is None:
        patch = 0
    lower = Version(major, minor, patch, prerelease)

    # Parse upper bound
    up_major, up_minor, up_patch, up_prerelease = _parse_version_parts(upper_str)

    if up_major is None:
        raise ValueError(f"Invalid hyphen range upper bound: {upper_str}")

    if up_minor is None:
        upper_comparators = [Comparator("<", Version(up_major + 1, 0, 0))]
    elif up_patch is None:
        upper_comparators = [Comparator("<", Version(up_major, up_minor + 1, 0))]
    else:
        upper_comparators = [Comparator("<=", Version(up_major, up_minor, up_patch, up_prerelease))]

    return [Comparator(">=", lower)] + upper_comparators


def _parse_comparator(s: str) -> List[Comparator]:
    """Parse a single comparator string, returning a list of comparators."""
    s = s.strip()
    if s == "":
        raise ValueError("Empty comparator")

    # Check for tilde
    if s.startswith("~"):
        return _parse_tilde(s[1:])

    # Check for caret
    if s.startswith("^"):
        return _parse_caret(s[1:])

    # Check for operators
    op = "="
    rest = s
    if s.startswith("<="):
        op = "<="
        rest = s[2:]
    elif s.startswith(">="):
        op = ">="
        rest = s[2:]
    elif s.startswith("<"):
        op = "<"
        rest = s[1:]
    elif s.startswith(">"):
        op = ">"
        rest = s[1:]
    elif s.startswith("="):
        op = "="
        rest = s[1:]

    rest = rest.strip()
    if rest == "":
        raise ValueError(f"Missing version in comparator: {s}")

    comparators = _expand_partial_version(rest, op)
    return comparators


def _parse_set(s: str) -> List[Comparator]:
    """Parse a single comparator set (space-separated comparators)."""
    s = s.strip()
    if s == "" or s == "*":
        return []

    # Check for hyphen range using regex
    m = re.match(r'^(\S+)\s*-\s*(\S+)$', s)
    if m:
        return _parse_hyphen(s)

    # Split into individual comparators by whitespace
    comparators = []
    tokens = s.split()
    for token in tokens:
        if token:
            comparators.extend(_parse_comparator(token))

    return comparators


def _parse_range(rng: str) -> List[List[Comparator]]:
    """Parse a range string into a list of comparator sets."""
    rng = rng.strip()
    if rng == "":
        return [[]]

    parts = rng.split("||")
    sets = []
    for part in parts:
        comparators = _parse_set(part)
        sets.append(comparators)
    return sets


def _set_matches(set_comparators: List[Comparator], v: Version) -> bool:
    """Check if a version matches a single comparator set."""
    # Prerelease rule
    if v.prerelease is not None:
        has_matching_prerelease = False
        for comp in set_comparators:
            if (comp.version.major == v.major and
                    comp.version.minor == v.minor and
                    comp.version.patch == v.patch and
                    comp.version.prerelease is not None):
                has_matching_prerelease = True
                break
        if not has_matching_prerelease:
            return False

    for comp in set_comparators:
        if not comp.matches(v):
            return False
    return True


def satisfies(version: str, rng: str) -> bool:
    """Check if a version string satisfies a range string."""
    v = parse(version)
    sets = _parse_range(rng)

    for set_comparators in sets:
        if _set_matches(set_comparators, v):
            return True
    return False


def max_satisfying(versions: List[str], rng: str) -> Optional[str]:
    """Return the highest version string that satisfies the range, or None."""
    best = None
    best_version = None

    for v_str in versions:
        try:
            v = parse(v_str)
        except ValueError:
            continue

        if satisfies(v_str, rng):
            if best_version is None or v > best_version:
                best_version = v
                best = v_str

    return best

