import re


def split_command(line: str, env: dict[str, str]) -> list[str]:
    words = []
    i = 0
    n = len(line)

    while i < n:
        c = line[i]
        # Skip unquoted whitespace (spaces, tabs, newlines)
        if c in (' ', '\t', '\n'):
            i += 1
            continue

        # Build a word by collecting segments
        # Each segment is (text, is_from_unquoted_expansion)
        segments = []  # List of (text, is_unquoted_expansion)
        has_quoted_part = False
        has_any_content = False

        while i < n:
            c = line[i]

            if c in (' ', '\t', '\n'):
                break

            if c == "'":
                # Single quote: everything literal up to next '
                i += 1
                start = i
                while i < n and line[i] != "'":
                    i += 1
                if i >= n:
                    raise ValueError("Unterminated single quote")
                segments.append((line[start:i], False))
                has_quoted_part = True
                has_any_content = True
                i += 1  # skip closing '

            elif c == '"':
                # Double quote: literal except \ escapes $, ", \, and newline
                i += 1
                buf = []
                while i < n:
                    ch = line[i]
                    if ch == '"':
                        break
                    if ch == '\\' and i + 1 < n:
                        nxt = line[i + 1]
                        if nxt in ('$', '"', '\\'):
                            buf.append(nxt)
                            i += 2
                        elif nxt == '\n':
                            # backslash-newline is removed
                            i += 2
                        else:
                            buf.append('\\')
                            i += 1
                    elif ch == '$':
                        expanded, new_i = _expand(line, i, env)
                        buf.append(expanded)
                        i = new_i
                    elif ch == '\\':
                        # Trailing backslash inside double quotes means unterminated quote
                        raise ValueError("Unterminated double quote")
                    else:
                        buf.append(ch)
                        i += 1
                if i >= n or line[i] != '"':
                    raise ValueError("Unterminated double quote")
                segments.append((''.join(buf), False))
                has_quoted_part = True
                has_any_content = True
                i += 1  # skip closing "

            elif c == '\\':
                # Unquoted backslash
                if i + 1 >= n:
                    raise ValueError("Trailing unescaped backslash")
                nxt = line[i + 1]
                if nxt == '\n':
                    # backslash-newline removed entirely
                    i += 2
                else:
                    segments.append((nxt, False))
                    has_any_content = True
                    i += 2

            elif c == '$':
                expanded, new_i = _expand(line, i, env)
                segments.append((expanded, True))  # Mark as from unquoted expansion
                has_any_content = True
                i = new_i

            else:
                segments.append((c, False))
                has_any_content = True
                i += 1

        if not has_any_content:
            continue

        # Now process the segments for field splitting
        # Field splitting applies to unquoted expansion results
        # If a word is entirely unquoted expansion(s) and becomes empty, remove it
        # Quoted parts are never split

        result_words = []

        # Check if all segments are from unquoted expansions (no quoted parts, no literal text)
        all_unquoted_expansion = (not has_quoted_part) and len(segments) > 0 and all(is_exp for _, is_exp in segments)

        if all_unquoted_expansion:
            # The entire word consists of unquoted expansion(s) only
            full_word = ''.join(text for text, _ in segments)
            fields = _split_on_whitespace(full_word)
            # If the result is empty or a single empty field, remove the word entirely
            if not fields or (len(fields) == 1 and fields[0] == ''):
                pass  # Remove this word
            else:
                result_words.extend(fields)
        else:
            # Mixed or has quoted parts - need to handle field splitting per segment
            # Build the full string and track which positions are protected from field splitting
            full_text = ''
            protected_mask = []  # True if position is protected (should not be split)

            for text, is_exp in segments:
                full_text += text
                if is_exp:
                    protected_mask.extend([False] * len(text))  # Unquoted expansion - splittable
                else:
                    protected_mask.extend([True] * len(text))   # Quoted or literal - protected

            if not full_text:
                # Word became empty
                if has_quoted_part:
                    result_words.append('')
            else:
                # Split on whitespace, but only in unprotected regions
                fields = []
                current = []

                for idx, ch in enumerate(full_text):
                    if ch in (' ', '\t', '\n') and not protected_mask[idx]:
                        if current:
                            fields.append(''.join(current))
                            current = []
                    else:
                        current.append(ch)

                if current:
                    fields.append(''.join(current))

                # If no fields were produced but there was content, return empty string
                if not fields and full_text:
                    result_words.append('')
                else:
                    result_words.extend(fields)

        words.extend(result_words)

    return words


def _expand(line: str, i: int, env: dict[str, str]) -> tuple[str, int]:
    """Handle $ expansion starting at position i. Returns (expanded_string, new_i)."""
    n = len(line)
    if i >= n:
        return '', i

    c = line[i]
    if c != '$':
        return c, i + 1

    i += 1  # skip $

    if i >= n:
        return '$', i

    c = line[i]

    if c == '{':
        # ${NAME}, ${NAME:-default}, ${NAME-default}
        i += 1  # skip {

        # Check if name starts with valid character
        if i >= n or not (line[i].isalpha() or line[i] == '_'):
            # Invalid name - scan to } and return literal including the $
            start = i
            while i < n and line[i] != '}':
                i += 1
            if i >= n:
                raise ValueError("Unterminated ${")
            # Return the whole thing as literal: $ + { ... }
            return '$' + line[start-1:i+1], i + 1

        name_start = i
        while i < n and (line[i].isalnum() or line[i] == '_'):
            i += 1
        name = line[name_start:i]

        if i >= n:
            raise ValueError("Unterminated ${")

        c = line[i]
        if c == '}':
            # Simple ${NAME}
            value = env.get(name, '')
            return value, i + 1
        elif c == ':' and i + 1 < n and line[i + 1] == '-':
            # ${NAME:-default}
            i += 2  # skip :-
            default_start = i
            # Find matching } with brace depth tracking
            depth = 0
            while i < n:
                if line[i] == '{':
                    depth += 1
                elif line[i] == '}':
                    if depth == 0:
                        break
                    depth -= 1
                i += 1
            if i >= n:
                raise ValueError("Unterminated ${")
            default_text = line[default_start:i]
            # The default text itself undergoes $ expansion
            expanded_default, _ = _expand_text(default_text, env)
            value = env.get(name, '')
            if value == '':  # unset or empty
                return expanded_default, i + 1
            else:
                return value, i + 1
        elif c == '-':
            # ${NAME-default}
            i += 1  # skip -
            default_start = i
            # Find matching } with brace depth tracking
            depth = 0
            while i < n:
                if line[i] == '{':
                    depth += 1
                elif line[i] == '}':
                    if depth == 0:
                        break
                    depth -= 1
                i += 1
            if i >= n:
                raise ValueError("Unterminated ${")
            default_text = line[default_start:i]
            expanded_default, _ = _expand_text(default_text, env)
            value = env.get(name, '')
            if name not in env:  # only if unset
                return expanded_default, i + 1
            else:
                return value, i + 1
        else:
            raise ValueError("Unterminated ${")

    elif c.isalpha() or c == '_':
        # $NAME - longest [A-Za-z_][A-Za-z0-9_]*
        start = i
        while i < n and (line[i].isalnum() or line[i] == '_'):
            i += 1
        name = line[start:i]
        value = env.get(name, '')
        return value, i

    else:
        # $ not followed by name or { is literal
        return '$', i


def _expand_text(text: str, env: dict[str, str]) -> tuple[str, int]:
    """Expand all $ references in a text string (for default values)."""
    result = []
    i = 0
    n = len(text)
    while i < n:
        if text[i] == '$':
            expanded, new_i = _expand(text, i, env)
            result.append(expanded)
            i = new_i
        else:
            result.append(text[i])
            i += 1
    return ''.join(result), i


def _split_on_whitespace(s: str) -> list[str]:
    """Split on spaces, tabs, and newlines."""
    if not s:
        return []
    fields = []
    current = []
    for c in s:
        if c in (' ', '\t', '\n'):
            if current:
                fields.append(''.join(current))
                current = []
        else:
            current.append(c)
    if current:
        fields.append(''.join(current))
    return fields
