The main real defect is that PEP 604 unions (`T | U`, which use `types.UnionType` as their origin) are not detected by `_is_optional` or `_is_union`, so they fall through to "Unsupported type annotation". I'll fix both helpers to also check for `types.UnionType`.

I'll also address the minor side-effect issue of mutating the module's globals dict (use a copy), and make string-annotation resolution more robust by using `typing.get_type_hints` on dataclasses where possible.

```python
from __future__ import annotations

import dataclasses
import sys
import types as _types_module
import typing
from typing import Any


class LoadError(ValueError):
    def __init__(self, path: str, message: str):
        self.path = path
        self._message = message
        super().__init__(f"{path}: {message}")


def _is_dataclass_type(tp: Any) -> bool:
    if isinstance(tp, type) and dataclasses.is_dataclass(tp):
        return True
    # Also handle the case where tp itself is a class that is a dataclass
    try:
        return dataclasses.is_dataclass(tp)
    except Exception:
        return False


def _is_list_type(tp: Any) -> bool:
    origin = typing.get_origin(tp)
    return origin is list


def _is_dict_type(tp: Any) -> bool:
    origin = typing.get_origin(tp)
    return origin is dict


def _is_tuple_type(tp: Any) -> bool:
    origin = typing.get_origin(tp)
    return origin is tuple


def _is_optional(tp: Any) -> bool:
    """Check if tp is Optional[T] (i.e., T | None)."""
    origin = typing.get_origin(tp)
    # PEP 585 / typing.Union
    if origin is typing.Union:
        args = typing.get_args(tp)
        if len(args) == 2 and type(None) in args:
            return True
    # PEP 604: T | None uses types.UnionType as origin
    if origin is _types_module.UnionType:
        args = typing.get_args(tp)
        if len(args) == 2 and type(None) in args:
            return True
    return False


def _is_union(tp: Any) -> bool:
    origin = typing.get_origin(tp)
    # PEP 585 / typing.Union
    if origin is typing.Union:
        return True
    # PEP 604: T | U uses types.UnionType as origin
    if origin is _types_module.UnionType:
        return True
    return False


def _get_union_members(tp: Any) -> list[Any]:
    return list(typing.get_args(tp))


def _is_literal_type(tp: Any) -> bool:
    origin = typing.get_origin(tp)
    if origin is typing.Literal:
        return True
    return False


def _get_literal_values(tp: Any) -> list[Any]:
    return list(typing.get_args(tp))


def _is_none_type(tp: Any) -> bool:
    return tp is type(None) or tp is None


def _load_value(tp: Any, data: Any, path: str, globalns: dict) -> Any:
    """Load a value from JSON-like data according to the type annotation tp."""

    # Resolve string annotations
    if isinstance(tp, str):
        try:
            tp = eval(tp, globalns)
        except Exception:
            raise LoadError(path, f"Cannot resolve type annotation '{tp}'")

    # Handle None type
    if _is_none_type(tp):
        if data is None:
            return None
        else:
            raise LoadError(path, f"Expected None, got {type(data).__name__}")

    # Handle Optional[T] (T | None)
    if _is_optional(tp):
        if data is None:
            return None
        # Get the non-None member
        args = typing.get_args(tp)
        non_none = [a for a in args if not _is_none_type(a)]
        if len(non_none) == 1:
            return _load_value(non_none[0], data, path, globalns)
        else:
            # Shouldn't happen for Optional, but handle as union
            return _load_union(tp, data, path, globalns)

    # Handle Union types (T | U | ...)
    if _is_union(tp):
        return _load_union(tp, data, path, globalns)

    # Handle Literal types
    if _is_literal_type(tp):
        return _load_literal(tp, data, path, globalns)

    # Handle dataclass types
    if _is_dataclass_type(tp):
        return _load_dataclass(tp, data, path, globalns)

    # Handle list[T]
    if _is_list_type(tp):
        return _load_list(tp, data, path, globalns)

    # Handle dict[str, T]
    if _is_dict_type(tp):
        return _load_dict(tp, data, path, globalns)

    # Handle tuple types
    if _is_tuple_type(tp):
        return _load_tuple(tp, data, path, globalns)

    # Handle basic types: int, float, str, bool
    if tp is int:
        if isinstance(data, bool):
            raise LoadError(path, f"Expected int, got bool")
        if isinstance(data, int):
            return data
        else:
            raise LoadError(path, f"Expected int, got {type(data).__name__}")

    if tp is float:
        if isinstance(data, bool):
            raise LoadError(path, f"Expected float, got bool")
        if isinstance(data, int):
            return float(data)
        if isinstance(data, float):
            return data
        else:
            raise LoadError(path, f"Expected float, got {type(data).__name__}")

    if tp is str:
        if isinstance(data, str):
            return data
        else:
            raise LoadError(path, f"Expected str, got {type(data).__name__}")

    if tp is bool:
        if isinstance(data, bool):
            return data
        else:
            raise LoadError(path, f"Expected bool, got {type(data).__name__}")

    # If we get here, the type is not recognized
    raise LoadError(path, f"Unsupported type annotation: {tp}")


def _load_union(tp: Any, data: Any, path: str, globalns: dict) -> Any:
    """Load a value for a union type, trying members left to right."""
    args = typing.get_args(tp)
    errors = []
    for member in args:
        try:
            return _load_value(member, data, path, globalns)
        except LoadError as e:
            errors.append(e)

    # None of the members worked; raise an error with the union's own path
    if errors:
        raise LoadError(path, f"Could not load value for union {tp}: tried {[str(m) for m in args]}, last error: {errors[-1]._message}")
    else:
        raise LoadError(path, f"Could not load value for union {tp}")


def _load_literal(tp: Any, data: Any, path: str, globalns: dict) -> Any:
    """Load a value for a Literal type."""
    literals = _get_literal_values(tp)
    for lit in literals:
        if data is None and lit is None:
            return data
        if data == lit and type(data) is type(lit):
            return data

    raise LoadError(path, f"Value {data!r} not in Literal values {literals}")


def _load_dataclass(cls: Any, data: Any, path: str, globalns: dict) -> Any:
    """Load a dataclass instance from a dict."""
    if not isinstance(data, dict):
        raise LoadError(path, f"Expected dict for dataclass {cls.__name__}, got {type(data).__name__}")

    # Get type hints for the dataclass using typing.get_type_hints
    try:
        hints = typing.get_type_hints(cls)
    except Exception as e:
        raise LoadError(path, f"Could not resolve type hints for {cls.__name__}: {e}")

    # Get fields
    fields = dataclasses.fields(cls)

    # Build kwargs
    kwargs = {}
    field_names = set()

    for field in fields:
        fname = field.name
        field_names.add(fname)

        if fname not in data:
            # Check for default or default_factory
            if field.default is not dataclasses.MISSING:
                kwargs[fname] = field.default
            elif field.default_factory is not dataclasses.MISSING:
                kwargs[fname] = field.default_factory()
            else:
                raise LoadError(f"{path}.{fname}", f"Missing required field '{fname}'")
        else:
            # Load the value
            annotation = hints.get(fname, Any)
            if isinstance(annotation, str):
                try:
                    annotation = eval(annotation, globalns)
                except Exception:
                    pass
            kwargs[fname] = _load_value(annotation, data[fname], f"{path}.{fname}", globalns)

    # Check for unknown keys in input dict order
    known_keys = set(field_names)
    for key in data.keys():
        if key not in known_keys:
            raise LoadError(f"{path}.{key}", f"Unknown field '{key}'")

    try:
        return cls(**kwargs)
    except TypeError as e:
        raise LoadError(path, f"Failed to construct {cls.__name__}: {e}")


def _load_list(tp: Any, data: Any, path: str, globalns: dict) -> Any:
    """Load a list from JSON data."""
    if not isinstance(data, list):
        raise LoadError(path, f"Expected list, got {type(data).__name__}")

    args = typing.get_args(tp)
    if len(args) != 1:
        raise LoadError(path, f"Expected list[T], but got list with {len(args)} type arguments")

    elem_type = args[0]
    result = []
    for i, item in enumerate(data):
        item_path = f"{path}[{i}]"
        result.append(_load_value(elem_type, item, item_path, globalns))

    return result


def _load_dict(tp: Any, data: Any, path: str, globalns: dict) -> Any:
    """Load a dict from JSON data."""
    if not isinstance(data, dict):
        raise LoadError(path, f"Expected dict, got {type(data).__name__}")

    args = typing.get_args(tp)
    if len(args) != 2:
        raise LoadError(path, f"Expected dict[K, V], but got dict with {len(args)} type arguments")

    key_type, val_type = args

    # For simplicity, we assume keys are strings (as per the spec: dict[str, T])
    result = {}
    for key, value in data.items():
        if not isinstance(key, str):
            raise LoadError(f"{path}.{key}", f"Expected string key, got {type(key).__name__}")

        # Load the value
        val_path = f"{path}.{key}"
        result[key] = _load_value(val_type, value, val_path, globalns)

    return result


def _load_tuple(tp: Any, data: Any, path: str, globalns: dict) -> Any:
    """Load a tuple from JSON data."""
    if not isinstance(data, list):
        raise LoadError(path, f"Expected list for tuple, got {type(data).__name__}")

    args = typing.get_args(tp)

    # Check if it's a variable-length tuple like tuple[T, ...]
    if len(args) == 2 and args[1] is Ellipsis:
        elem_type = args[0]
        result = []
        for i, item in enumerate(data):
            item_path = f"{path}[{i}]"
            result.append(_load_value(elem_type, item, item_path, globalns))
        return tuple(result)
    else:
        # Fixed-length tuple
        if len(data) != len(args):
            raise LoadError(path, f"Expected tuple of length {len(args)}, got list of length {len(data)}")

        result = []
        for i, (item, elem_type) in enumerate(zip(data, args)):
            item_path = f"{path}[{i}]"
            result.append(_load_value(elem_type, item, item_path, globalns))
        return tuple(result)


def load(cls: Any, data: Any) -> Any:
    """Build an instance of a (possibly nested) @dataclass type cls from JSON-like data."""
    # Get the module's globals for resolving string annotations (copy to avoid side effects)
    module = sys.modules.get(cls.__module__)
    if module is not None:
        globalns = dict(vars(module))
    else:
        globalns = {}

    # Add common types to globalns for resolution
    globalns.setdefault('int', int)
    globalns.setdefault('float', float)
    globalns.setdefault('str', str)
    globalns.setdefault('bool', bool)
    globalns.setdefault('list', list)
    globalns.setdefault('dict', dict)
    globalns.setdefault('tuple', tuple)
    globalns.setdefault('Optional', typing.Optional)
    globalns.setdefault('Literal', typing.Literal)

    return _load_value(cls, data, "$", globalns)
