usage() {
    echo "Usage: $0 [-d DELIM] [-s] COLUMN [FILE]" >&2
    exit 1
}

DELIM=","
SUMMARY=0
COLUMN=""
FILE=""

while getopts ":d:s" opt; do
    case "$opt" in
        d) DELIM="$OPTARG";;
        s) SUMMARY=1;;
        \?) echo "Invalid option: -$OPTARG" >&2; usage;;
